package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"net/url"
	"os"
	"strings"

	"github.com/gorilla/websocket"
)

var (
	upgrader = websocket.Upgrader{
		ReadBufferSize:  1024,
		WriteBufferSize: 1024,
		CheckOrigin:     checkOrigin,
	}
	allowedHosts []string
	hmacSecret   []byte
	redirectBase string
)

func init() {
	hosts := os.Getenv("ALLOWED_ORIGINS")
	if hosts == "" {
		hosts = "localhost,example.com"
	}
	allowedHosts = strings.Split(hosts, ",")

	secret := os.Getenv("HMAC_SECRET")
	if secret == "" {
		secret = "default-dev-secret-key-32bytes!!"
	}
	hmacSecret = []byte(secret)

	redirectBase = os.Getenv("REDIRECT_BASE")
	if redirectBase == "" {
		redirectBase = "https://example.com"
	}
}

func checkOrigin(r *http.Request) bool {
	origin := r.Header.Get("Origin")
	if origin == "" {
		return true
	}
	parsed, err := url.Parse(origin)
	if err != nil {
		return false
	}
	for _, allowed := range allowedHosts {
		if strings.HasSuffix(parsed.Hostname(), allowed) {
			return true
		}
	}
	return false
}

func computeRedirectMAC(target string) string {
	mac := hmac.New(sha256.New, hmacSecret)
	mac.Write([]byte(target))
	return hex.EncodeToString(mac.Sum(nil))
}

func validateRedirectMAC(target, signature string) bool {
	expected := computeRedirectMAC(target)
	return hmac.Equal([]byte(expected), []byte(signature))
}

func normalizeRedirectTarget(target string) (string, error) {
	parsed, err := url.Parse(target)
	if err != nil {
		return "", fmt.Errorf("invalid URL: %w", err)
	}

	base, err := url.Parse(redirectBase)
	if err != nil {
		return "", fmt.Errorf("invalid base: %w", err)
	}

	// If target is relative, resolve against base
	if !parsed.IsAbs() {
		resolved := base.ResolveReference(parsed)
		return resolved.String(), nil
	}

	// For absolute URLs, verify the host matches our allowed list
	if isAllowedRedirectHost(parsed.Hostname()) {
		return parsed.String(), nil
	}

	return "", fmt.Errorf("disallowed redirect host: %s", parsed.Hostname())
}

func isAllowedRedirectHost(hostname string) bool {
	for _, allowed := range allowedHosts {
		if strings.HasSuffix(hostname, "."+allowed) || hostname == allowed {
			return true
		}
	}
	return false
}

func handleWSConnection(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		msgType, msg, err := conn.ReadMessage()
		if err != nil {
			break
		}
		if msgType == websocket.TextMessage {
			handleCommand(conn, string(msg))
		}
	}
}

func handleCommand(conn *websocket.Conn, msg string) {
	parts := strings.SplitN(msg, "|", 3)
	if len(parts) < 2 {
		conn.WriteMessage(websocket.TextMessage, []byte("ERR|invalid format"))
		return
	}

	switch parts[0] {
	case "REDIRECT":
		if len(parts) != 3 {
			conn.WriteMessage(websocket.TextMessage, []byte("ERR|need target and sig"))
			return
		}
		target := parts[1]
		sig := parts[2]

		if !validateRedirectMAC(target, sig) {
			conn.WriteMessage(websocket.TextMessage, []byte("ERR|invalid signature"))
			return
		}

		normalized, err := normalizeRedirectTarget(target)
		if err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte("ERR|"+err.Error()))
			return
		}

		conn.WriteMessage(websocket.TextMessage, []byte("REDIRECT|"+normalized))

	case "SIGN":
		target := parts[1]
		sig := computeRedirectMAC(target)
		conn.WriteMessage(websocket.TextMessage, []byte("SIG|"+sig))

	default:
		conn.WriteMessage(websocket.TextMessage, []byte("ERR|unknown command"))
	}
}

func handleHTTPRedirect(w http.ResponseWriter, r *http.Request) {
	target := r.URL.Query().Get("url")
	sig := r.URL.Query().Get("sig")

	if target == "" || sig == "" {
		http.Error(w, "Missing parameters", http.StatusBadRequest)
		return
	}

	if !validateRedirectMAC(target, sig) {
		http.Error(w, "Invalid signature", http.StatusForbidden)
		return
	}

	normalized, err := normalizeRedirectTarget(target)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	http.Redirect(w, r, normalized, http.StatusFound)
}

func main() {
	http.HandleFunc("/ws", handleWSConnection)
	http.HandleFunc("/redirect", handleHTTPRedirect)

	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = ":8080"
	}

	log.Printf("Server starting on %s", addr)
	log.Fatal(http.ListenAndServe(addr, nil))
}
